"""Build a compact review with unchanged legacy debugger embedded on request."""
import json
from photo2.r297.common import ROOT,read
from .analyze import PRINCIPAL,LABELS

def main():
    d=read(ROOT/'photo2/r300/results/analysis.json');ledger=read(ROOT/'photo2/r300/results/ledger.json');out=ROOT/'photo2/review/r300'
    bundle=dict(models=list(d['models']),ledger=ledger,seams={k:v['seam']['centroid']['fraction'] for k,v in d['models'].items()})
    (out/'data.js').write_text('const DATA='+json.dumps(bundle,separators=(',',':'))+';\n')
    rows=''
    for name,label in zip(PRINCIPAL,LABELS):
        s=d['models'][name]['groups']['centroid']['trusted'];b=s['parallel']['sector_bootstrap_95'];rows+=f'<tr><td>{label}</td><td>{s["predicted"]}/45</td><td>{s["magnitude_quantiles"][0]:.2f}</td><td>{s["diameter_quantiles"][0]:.2f}</td><td>{s["parallel"]["slope"]:+.2f}</td><td>{s["normal"]["slope"]:+.2f}</td><td>{s["magnitude"]["slope"]:+.2f}</td><td>{b[0]:+.1f} … {b[1]:+.1f}</td></tr>'
    (out/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>R300 · Circuit diagnosis</title>
<style>body{font:16px system-ui,sans-serif;margin:0;background:#f5f4ef;color:#172830}header,main{max-width:1250px;margin:auto;padding:20px}h1{font-size:27px}p{max-width:1000px;line-height:1.5}button,select{font:inherit;padding:8px;margin:4px;max-width:95%}button{cursor:pointer}a{color:#086c82}.scroll{overflow:auto}table{border-collapse:collapse;min-width:850px}td,th{padding:9px;border-bottom:1px solid #ccc;text-align:right}td:first-child,th:first-child{text-align:left}img{width:100%;height:auto}canvas{width:100%;height:390px;background:white;border:1px solid #bbb;box-sizing:border-box}iframe{width:100%;height:1100px;border:0}#readout{min-height:60px}figure{margin:28px 0}figcaption{line-height:1.5}.note{background:#fff4d9;padding:14px}nav{display:flex;flex-wrap:wrap;gap:.35em}summary{cursor:pointer;padding:12px;background:#e5e9e7}</style>
<header><h1>R300 · Reflection errors around the circuit</h1><p class="note"><strong>No evidence of runaway error magnitude; signed regional bias remains.</strong> R299's phase adjustment increases the along-chain trend. Frozen local ownership and sparse coverage cannot establish stable physical indexing or the join. Retain approximate optics; do not launch a larger whole-necklace fit yet.</p><nav><a href="../../R300_REPORT.md">Report</a> · <a href="../../R300_REPRODUCE.md">Reproduce</a> · <a href="../../r300/results/analysis.json">Analysis JSON</a> · <a href="../../r300/results/residuals.csv">Residual CSV</a> · <a href="../../r300/results/crossed-controls.json">Two crossed controls</a> · <a href="../r299/index.html">Original R299 debugger</a> · <a href="../r298/index.html">Original R298 debugger</a> · <a href="../../r297/results/pilot/review/debug.html">R297 debugger</a></nav></header>
<main><p>All 52 observations and all 19 native model/source exports stay fixed. Summary uses 45 stronger candidates; finite medians exclude missing predictions, whose denominator is shown. Slopes are pixels per full photographic circuit from bead zero. Resampling ranges describe sensitivity to spatial sectors, not physical confidence bounds.</p><div class="scroll"><table><thead><tr><th>Family</th><th>Predicted</th><th>Median px</th><th>Median diameters</th><th>Parallel slope</th><th>Normal slope</th><th>Magnitude slope</th><th>Parallel sector-resampling 95%</th></tr></thead><tbody>'''+rows+'''</tbody></table></div>
<h2>Inspect every frozen residual</h2><label>Model <select id="model"></select></label><label>Location measure <select id="kind"><option value="centroid">Centroid</option><option value="peak">Peak</option></select></label><label>Component <select id="component"><option value="0">Parallel (px)</option><option value="1">Normal (px)</option><option value="diameters">Magnitude / diameter</option><option value="index">Index-equivalent displacement</option></select></label>
<canvas id="plot" width="1200" height="390" aria-label="Residual versus circuit position; click a point to inspect its original photograph"></canvas><p id="readout">Click a point for its frozen owner, alternatives, and original photo. Blue: stronger candidate; gray: ambiguous mixture; ring: ambiguous owner; red cross: missing prediction. The red vertical line is this model's index seam. Empty stretches are unobserved.</p><button id="inspect" disabled>Inspect selected point in original debugger</button><button id="toggle">Show original R299 / R298 debugger</button><div id="legacy" hidden><iframe id="debugger" title="Unchanged R299 reflection and R298 geometry debugger"></iframe></div>
<figure><a href="circuit-residuals.png"><img src="circuit-residuals.png" alt="Signed parallel, normal and diameter-normalized centroid errors across six families" loading="lazy"></a><figcaption>Open markers preserve uncertain owners; black bars show bin means. No absolute accuracy gate is imposed.</figcaption></figure>
<details><summary>Index-equivalent displacements and cumulative-difference diagnostic</summary><img src="index-diagnostics.png" alt="Conditional index displacement and telescoping differences"><p>Dividing a reflection displacement by centerline pitch is a scale diagnostic. It is not an observed integer error. Summing changes telescopes to endpoint difference; summing location residuals would manufacture accumulation.</p></details>
<details><summary>Native transverse widths, boundary placement and regional bias</summary><img src="geometry-and-bias.png" alt="Independent native width and edge errors and descriptive CUSUM"></details>
<details><summary>Full-photo coverage and proposed seams</summary><img src="coverage.png" alt="Original photograph with circuit bins and actual index seams"></details>
<p>Missing observations, local ownership alternatives and all failed hypotheses remain. No reconstruction or color pattern is adopted. Stop for review.</p></main>
<script src="data.js"></script><script>
const model=document.querySelector('#model'),kind=document.querySelector('#kind'),component=document.querySelector('#component'),canvas=document.querySelector('#plot'),ctx=canvas.getContext('2d');let plotted=[],selected=null;
DATA.models.forEach(n=>model.add(new Option(n,n)));model.value='joint-15';
function draw(){let rows=DATA.ledger.filter(r=>r.model===model.value);ctx.clearRect(0,0,1200,390);let low=component.value==='diameters'?0:component.value==='index'?-7:-30,high=component.value==='diameters'?1.2:component.value==='index'?7:30;const Y=v=>335-(v-low)/(high-low)*285;ctx.font='14px system-ui';ctx.strokeStyle='#ddd';ctx.fillStyle='#333';for(let i=0;i<=10;i++){let x=60+110*i;ctx.beginPath();ctx.moveTo(x,40);ctx.lineTo(x,335);ctx.stroke();ctx.fillText(i*10+'%',x-12,360)}for(let i=0;i<=4;i++){let v=low+(high-low)*i/4,y=Y(v);ctx.fillText(v.toFixed(1),5,y+4);ctx.beginPath();ctx.moveTo(60,y);ctx.lineTo(1160,y);ctx.stroke()}ctx.fillText('Photographic circuit from bead-zero reference',400,385);let sx=60+1100*DATA.seams[model.value];ctx.strokeStyle='#c33';ctx.setLineDash([6,4]);ctx.beginPath();ctx.moveTo(sx,30);ctx.lineTo(sx,335);ctx.stroke();ctx.setLineDash([]);ctx.fillText('index seam',sx+5,24);plotted=[];rows.forEach(r=>{let val=r.exists?(component.value==='diameters'?r[kind.value+'_diameters']:component.value==='index'?r[kind.value+'_index_equivalent']:r[kind.value+'_tn'][+component.value]):0;let x=60+1100*r.fraction,y=Y(val);ctx.strokeStyle=r.exists?(r.trusted?'#087c9a':'#888'):'#c22';ctx.fillStyle=ctx.strokeStyle;ctx.beginPath();if(!r.exists){ctx.moveTo(x-5,y-5);ctx.lineTo(x+5,y+5);ctx.moveTo(x+5,y-5);ctx.lineTo(x-5,y+5);ctx.stroke()}else{ctx.arc(x,y,5,0,Math.PI*2);if(r.ownership_ambiguous)ctx.stroke();else ctx.fill()}plotted.push({x,y,r,val})});}
[model,kind,component].forEach(el=>el.onchange=()=>{selected=null;document.querySelector('#inspect').disabled=true;draw()});
canvas.onclick=e=>{let rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*1200/rect.width,y=(e.clientY-rect.top)*390/rect.height;selected=plotted.reduce((a,b)=>(a.x-x)**2+(a.y-y)**2<(b.x-x)**2+(b.y-y)**2?a:b);let r=selected.r;document.querySelector('#readout').textContent=`${r.id} · ${(r.fraction*100).toFixed(2)}% circuit · ${r.color} · ${r.exists?selected.val.toFixed(3):'missing prediction: '+r.missing_reason} · frozen index ${r.index}; alternatives ${r.competing_indices.join(', ')} · ${r.ownership_ambiguous?'ownership ambiguous':'owner passes original dominance screen (not verified identity)'}`;document.querySelector('#inspect').disabled=false};
const frame=document.querySelector('#debugger');function show(){document.querySelector('#legacy').hidden=false;if(!frame.getAttribute('src'))frame.src='../r299/index.html'}
document.querySelector('#toggle').onclick=()=>{if(document.querySelector('#legacy').hidden)show();else document.querySelector('#legacy').hidden=true};
document.querySelector('#inspect').onclick=()=>{show();let attempts=0;const timer=setInterval(()=>{try{let doc=frame.contentDocument,ms=doc.querySelector('#model'),os=doc.querySelector('#observation');if(ms&&os&&os.options.length===52){ms.value=model.value;ms.dispatchEvent(new Event('change',{bubbles:true}));let rr=DATA.ledger.filter(r=>r.model===model.value);os.value=String(rr.findIndex(r=>r.id===selected.r.id));os.dispatchEvent(new Event('change',{bubbles:true}));clearInterval(timer);frame.scrollIntoView({block:'start'})}}catch(e){clearInterval(timer)}if(++attempts>50)clearInterval(timer)},100)};draw();
</script></html>''')
if __name__=='__main__':main()
